changeSet.sql:
DO $$
DECLARE
    site record;
    new_id numeric;
    site_type_id numeric;
BEGIN
    SELECT id INTO site_type_id FROM clinlims.organization_type WHERE short_name = 'sampling site';
    FOR site IN SELECT * FROM clinlims.vector_sampling_site WHERE organization_id IS NULL ORDER BY id LOOP
        new_id := nextval('clinlims.organization_seq');
        INSERT INTO clinlims.organization (id, name, code, short_name, is_active, mls_sentinel_lab_flag,
            phone, contact_name, gps_latitude, gps_longitude, description, org_id, lastupdated, fhir_uuid,
            source)
        VALUES (new_id, left(site.name, 200), left(site.code, 20), left(site.code, 15),
            CASE WHEN coalesce(site.active, true) THEN 'Y' ELSE 'N' END, 'N',
            left(site.contact_phone, 20), left(site.contact_name, 100),
            CASE WHEN site.gps_latitude ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' THEN trim(site.gps_latitude)::numeric ELSE NULL END,
            CASE WHEN site.gps_longitude ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' THEN trim(site.gps_longitude)::numeric ELSE NULL END,
            left(site.description, 1000),
            CASE WHEN site.location_org_id ~ '^[0-9]+$'
                      AND EXISTS (SELECT 1 FROM clinlims.organization p WHERE p.id = site.location_org_id::numeric)
                 THEN site.location_org_id::numeric ELSE NULL END,
            now(), gen_random_uuid(), coalesce(site.source, 'LOCAL'));
        INSERT INTO clinlims.organization_organization_type (org_id, org_type_id) VALUES (new_id, site_type_id);
        IF site.code IS NOT NULL AND trim(site.code) <> '' THEN
            INSERT INTO clinlims.organization_identifier (id, organization_id, label, value, is_reporting, lastupdated)
            VALUES (nextval('clinlims.organization_identifier_seq'), new_id, 'Code', trim(site.code), true, now());
        END IF;
        UPDATE clinlims.vector_sampling_site SET organization_id = new_id WHERE id = site.id;
    END LOOP;
END $$;
